package com.hbm.satellite.control;
import com.hbm.satellite.*;import com.hbm.multiblock.MuffledMachine;import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.AbstractContainerMenu;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;
/** Actual three-slot satellite programmer, no HE, no fabricated computer callback. */
public final class SatelliteLinkerBlockEntity extends BlockEntity implements WorldlyContainer,MenuProvider,Nameable,MuffledMachine {
 public static final int SAT_ID_RANGE=10_000_000;private final NonNullList<ItemStack> slots=NonNullList.withSize(3,ItemStack.EMPTY);private Component customName;private boolean muffled,tilted;
 public SatelliteLinkerBlockEntity(BlockPos pos,BlockState state){super(SatelliteControlContent.ENTITY.get(),pos,state);}
 public void tick(){if(!(level instanceof net.minecraft.server.level.ServerLevel server))return;if(!slots.get(0).isEmpty()&&!slots.get(1).isEmpty()&&slots.get(0).getItem() instanceof SatelliteFrequency&&slots.get(1).getItem() instanceof SatelliteFrequency){int freq=SatelliteFrequency.getFreqS(slots.get(0));if(freq!=SatelliteFrequency.getFreqS(slots.get(1))){SatelliteFrequency.setFreqS(slots.get(1),freq);setChanged();}}if(!slots.get(2).isEmpty()&&slots.get(2).getItem() instanceof SatelliteFrequency){int frequency=level.random.nextInt(SAT_ID_RANGE);if(!SatelliteSavedData.getData(server).isFreqTaken(frequency)){SatelliteFrequency.setFreqS(slots.get(2),frequency);setChanged();}}}
 @Override public int getContainerSize(){return 3;}@Override public boolean isEmpty(){return slots.stream().allMatch(ItemStack::isEmpty);}@Override public ItemStack getItem(int slot){return slots.get(slot);}@Override public void setItem(int slot,ItemStack stack){slots.set(slot,stack);stack.limitSize(64);setChanged();}@Override public ItemStack removeItem(int slot,int count){var result=ContainerHelper.removeItem(slots,slot,count);if(!result.isEmpty())setChanged();return result;}@Override public ItemStack removeItemNoUpdate(int slot){return ContainerHelper.takeItem(slots,slot);}@Override public void clearContent(){slots.clear();setChanged();}@Override public boolean stillValid(Player player){return level!=null&&level.getBlockEntity(worldPosition)==this&&player.distanceToSqr(worldPosition.getX()+.5,worldPosition.getY()+.5,worldPosition.getZ()+.5)<=144;}
 @Override public boolean canPlaceItem(int slot,ItemStack stack){return stack.getItem() instanceof SatelliteFrequency;}@Override public int[] getSlotsForFace(Direction side){return new int[]{1};}@Override public boolean canPlaceItemThroughFace(int slot,ItemStack stack,Direction side){return canPlaceItem(slot,stack);}@Override public boolean canTakeItemThroughFace(int slot,ItemStack stack,Direction side){return SatelliteFrequency.getFreqS(slots.get(0))==SatelliteFrequency.getFreqS(slots.get(1));}
 @Override public Component getName(){return customName==null?Component.translatable("container.satLinker"):customName;}@Override public Component getDisplayName(){return getName();}@Override public boolean hasCustomName(){return customName!=null;}@Override public Component getCustomName(){return customName;}public void setCustomName(Component name){customName=name;setChanged();}@Override public AbstractContainerMenu createMenu(int id,Inventory inventory,Player player){return new SatelliteLinkerMenu(id,inventory,this);}
 @Override public boolean isMuffled(){return muffled;}@Override public void setMuffled(boolean value){muffled=value;setChanged();}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);var list=new ListTag();for(int i=0;i<3;i++)if(!slots.get(i).isEmpty()){var entry=(CompoundTag)slots.get(i).save(lookup);entry.putByte("slot",(byte)i);list.add(entry);}tag.put("items",list);if(customName!=null)tag.putString("name",Component.Serializer.toJson(customName,lookup));tag.putBoolean("muffled",muffled);tag.putBoolean("tilted",tilted);}
 @Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);slots.clear();for(var value:tag.getList("items",Tag.TAG_COMPOUND)){var entry=(CompoundTag)value;int slot=entry.getByte("slot");if(slot>=0&&slot<3)slots.set(slot,ItemStack.parseOptional(lookup,entry));}muffled=tag.getBoolean("muffled");tilted=tag.getBoolean("tilted");customName=null;if(tag.contains("name")){var name=tag.getString("name");try{customName=Component.Serializer.fromJson(name,lookup);}catch(com.google.gson.JsonParseException ignored){customName=Component.literal(name);}if(customName==null&&!name.isEmpty())customName=Component.literal(name);}}
}
